python3 - <<'EOF' 2>&1 | tail -20
import hashlib, json, os, tempfile, traceback
from carbon_market import audit, audit_proof
tmp = tempfile.mkdtemp()
journal=os.path.join(tmp,"a.json"); cp=os.path.join(tmp,"cp.json"); pp=os.path.join(tmp,"pp.json"); trust=os.path.join(tmp,"trust")
def ev(k): return {"op":"copy","target":"t","key":k,"changed":True,"error":None,"stage":None}
def export():
    p=audit_proof.export(journal,cp,"g1")
    json.dump(p,open(pp,"w"),ensure_ascii=False)
def vb():
    raw=open(cp,"rb").read(); tag='"'+hashlib.sha256(raw).hexdigest()+'"'
    return audit_proof.verify_bundle(cp,pp,tag,trust_dir=trust)
audit.record(journal,"a",ev("a")); export(); print(vb()["generation"])
audit.record(journal,"b",ev("b")); export()
try:
    print(vb()["generation"])
except Exception:
    traceback.print_exc()
EOF

